INSERT INTO claims (claim_id,site_id,field,value,evidence_class,source_id,scope,observed_date) VALUES ('CL011-07','CN0245','项目规模','共沉淀400t/a、浸渍600t/a，副硝酸钠约830t/a；设计转载','WEB_SECONDARY','W11S04','公示表项目概况','2026-07-16');
INSERT INTO claims (claim_id,site_id,field,value,evidence_class,source_id,scope,observed_date) VALUES ('CL011-08','CN0245','审批状态','转载公示绍市环审[2026]40号，审批时间2026-08-03；附件未获','WEB_SECONDARY','W11S05','公示第1项','2026-08-03');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N011-01','CN0077','W11S01','实际工艺及药剂','4.1.2，印刷26—32','含铬调节、亚硫酸氢钠还原、NaOH碱沉、混凝絮凝，两级间新增备用调pH/还原，二级Met-clear重金属捕集；车间达标才入总池，其他因子超标可转非含铬站。非含铬pH8–9、混凝、缺氧补碳、好氧、MBR；硝化液和污泥回流；板框脱水；除盐水浓水旁路总池。截图超限，按文字，不声称图完整复核。','WEB_PRIMARY','公开正文改写；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N011-02','CN0077','W11S01','水量及能力冲突','4.1.2；5.1.1.2；9.2.1.4；登记表','正文132t/d含铬，登记表134t/d；非含铬150t/d。设计纳管376.9t/d；2022年6、8月合计10425t，达产66988t/a折算、允许100622t/a。尾水按50/5mg/L核算COD3.349、氨氮0.335t/a，不是本厂实测负荷。','WEB_PRIMARY','公开正文改写；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N011-03','CN0077','W11S01','投资','4.5.4及登记表','实际总投资53800万元、实际环保5580万元，其中废水2500万元；原概算59746、环保4000万元。实际运行费用、膜面积、压力、通量、CIP及寿命待核。','WEB_PRIMARY','公开正文改写；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N011-04','CN0077','W11S01','监测与矛盾','9.2.1.2、9.2.2、表9.2-2至9.2-7','总排口、车间、雨水三处在线；铬在检出限附近在线总铬/六价铬倒挂，报告归因基线漂移；保留监测统计口径。表9.2-7氨氮96.3%、TN89.9%、SS77.5%，正文整数概括不重复入库。混凝泥正文写入含铬浓缩池，需原图复核。','WEB_PRIMARY','公开正文改写；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N011-05','CN0097','W11S03','初雨及事故池','印刷165页表6.1-3第12项','初期雨水池400m³、事故池1100m³已建；园区防控资料非实际日水量，未披露生产污水处理单元；截图受限。','WEB_PRIMARY','公开正文改写；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N011-06','CN0245','W11S04','项目废水及副产品','拟审批表','400吨共沉淀、600吨浸渍设计，副硝酸钠约830吨/年。干燥/焙烧等冷凝水蒸发除重，和其他废水入企业站后纳管；不可判断膜、工艺或实际运行。','WEB_SECONDARY','转载正文，附件未取得','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N011-07','CN0245','W11S05','审批索引','第1项','绍市环审[2026]40号，2026-08-03审批、8月6日公示；附件未读，不升级证据。','WEB_SECONDARY','转载索引','2026-11-27');
