INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA011-01','MR011-01','CN0077','chromium','screening',1,'回用减排或适用性初筛','优先保持Cr(VI)还原和车间独立达标；仅在有回用目标时以达标出水试UF/RO，金属浓水独立处置','conditional','未核实际工艺、浓水/残余物处置及回用需求前不作可实施结论','INFERRED；D011-01及关联废水证据','若历史/设计仍与实际相符，且存在明确回用或减量目标','2026实际水量、TDS、铬波动、膜进水指标、浓水与污泥成本；132/134t/d待核','核验许可、投运、实际多时段水质和流量；预处理、膜通量/截留、CIP小试及连续中试；产浓水/盐泥衡算、成本和合规审查','两级还原沉淀和捕集优化',NULL,NULL,NULL,NULL,NULL,NULL,'六维缺实际参数，不填假定分数','2026-11-27');
