INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA011-09','MR011-09','CN0038','mixed-production','screening',1,'回用减排或适用性初筛','生化出水先测溶剂残留和盐，再试UF/RO回用；不以膜替代蒸馏','conditional','未核实际工艺、浓水/残余物处置及回用需求前不作可实施结论','INFERRED；D011-09及关联废水证据','若历史/设计仍与实际相符，且存在明确回用或减量目标','催化剂专属水量不明、真实溶剂浓度、膜兼容性、浓水与回用成本','核验许可、投运、实际多时段水质和流量；预处理、膜通量/截留、CIP小试及连续中试；产浓水/盐泥衡算、成本和合规审查','溶剂回收、蒸发及生化优化',NULL,NULL,NULL,NULL,NULL,NULL,'六维缺实际参数，不填假定分数','2026-11-27');
