INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA011-11','MR011-11','CN0214','fluorinated-process','screening',1,'回用减排或适用性初筛','先对含氟、铬钴及氨废水完成分质与脱氨；仅在低温蒸发前液可相容且有浓水闭合时试NF/RO','conditional','未核实际工艺、浓水/残余物处置及回用需求前不作可实施结论','INFERRED；D011-11及关联废水证据','若历史/设计仍与实际相符，且存在明确回用或减量目标','原水氟、金属、pH、盐，低温蒸发能力，纯水RO不等于污水RO；实际投运待核','核验许可、投运、实际多时段水质和流量；预处理、膜通量/截留、CIP小试及连续中试；产浓水/盐泥衡算、成本和合规审查','维持蒸氨及低温蒸发；优化浓水回用',NULL,NULL,NULL,NULL,NULL,NULL,'六维缺实际参数，不填假定分数','2026-11-27');
