INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA011-12','MR011-12','CN0233','scr-regeneration','screening',1,'回用减排或适用性初筛','先验证沉淀后金属和盐度；若渗透压允许，旁路UF+RO或NF减量MVR','conditional','未核实际工艺、浓水/残余物处置及回用需求前不作可实施结论','INFERRED；D011-12及关联废水证据','若历史/设计仍与实际相符，且存在明确回用或减量目标','17t/h与14529.6m³/a设计口径差异，实际进水及蒸发负荷、盐去向、成本','核验许可、投运、实际多时段水质和流量；预处理、膜通量/截留、CIP小试及连续中试；产浓水/盐泥衡算、成本和合规审查','直接MVR及源头减水；优化调pH',NULL,NULL,NULL,NULL,NULL,NULL,'六维缺实际参数，不填假定分数','2026-11-27');
