INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA011-26','MR011-26','CN0090','factory-drainage','screening',1,'回用减排或适用性初筛','历史生产不用工艺水；优先初雨及冷却排水分流，只有稳定低盐流量且有回用需求时考虑膜','conditional','未核实际工艺、浓水/残余物处置及回用需求前不作可实施结论','INFERRED；D011-26及关联废水证据','若历史/设计仍与实际相符，且存在明确回用或减量目标','现行工艺、实际水量、雨水波动、回用需求及经济性；历史3869.8m³/a合计','核验许可、投运、实际多时段水质和流量；预处理、膜通量/截留、CIP小试及连续中试；产浓水/盐泥衡算、成本和合规审查','分流清洁公用水、沉淀后回用可行性',NULL,NULL,NULL,NULL,NULL,NULL,'六维缺实际参数，不填假定分数','2026-11-27');
INSERT INTO w11_assert SELECT count(*)=26 FROM process_diagrams WHERE diagram_id LIKE 'D011-%';
INSERT INTO w11_assert SELECT count(*)=0 FROM process_diagram_evidence e JOIN process_diagrams d USING(diagram_id) JOIN wastewater w USING(water_id) WHERE d.diagram_id LIKE 'D011-%' AND (d.site_id<>w.site_id OR e.source_id<>w.source_id);
INSERT INTO w11_assert SELECT count(*)=0 FROM process_diagram_evidence e JOIN process_diagrams d USING(diagram_id) WHERE d.diagram_id LIKE 'D011-%' AND NOT EXISTS(SELECT 1 FROM site_sources a WHERE a.site_id=d.site_id AND a.source_id=e.source_id);
